// Observe the exact link generated by the site's normal download action.
// No image URLs are guessed, and no cookies or website tokens are read.
(()=>{
 if(window.top!==window||window.__artOriginalLinkBridge)return;window.__artOriginalLinkBridge=true;
 let armed=null;
 window.addEventListener('message',e=>{if(e.source===window&&e.origin===location.origin&&e.data?.type==='ART_ORIGINAL_ARM'&&typeof e.data.nonce==='string')armed={nonce:e.data.nonce,source:location.href,expires:Date.now()+30*60*1000};});
 function report(a){if(!armed||Date.now()>armed.expires||location.href!==armed.source)return;const href=a.href,name=a.download||'';
  if(!href||(!name&&!/^blob:/.test(href)&&!(/\.(?:jpe?g|png|webp)(?:[?#]|$)/i.test(href))))return;
  if(!/^(?:https:\/\/|blob:https:\/\/)/.test(href))return;
  window.postMessage({type:'ART_ORIGINAL_LINK',nonce:armed.nonce,source:location.href,href,filename:String(name).slice(0,240)},location.origin);
 }
 const click=HTMLAnchorElement.prototype.click;HTMLAnchorElement.prototype.click=function(...args){report(this);return click.apply(this,args);};
 const dispatch=HTMLAnchorElement.prototype.dispatchEvent;HTMLAnchorElement.prototype.dispatchEvent=function(event){if(event?.type==='click')report(this);return dispatch.call(this,event);};
 window.addEventListener('click',e=>{const a=e.target?.closest?.('a');if(a)report(a);},true);
})();
